package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Normalizes a create-owner request's {@code address} to its canonical form (see
 * {@link AddressNormalizer}: trim, collapse whitespace, upper-case, expand common abbreviations) before
 * any other step runs. Binds the request body (the single {@code @RequestBody} step of this pipeline)
 * and republishes it as a variable for the later steps. Because it runs first, the normalized value is
 * what {@link RequireOwnerFields} tests for blankness, what the household component of the derived
 * {@link IdentityKey} is built from, and what {@link BuildOwner} maps to the entity — so a blank-after-normalization address is rejected
 * and the normalized {@code address} is stored and returned.
 */
public class NormalizeAddress {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> normalized) {
        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
        normalized.set(request);
    }
}

===== AddressNormalizer.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Map;

/**
 * Canonical form of an owner's postal {@code address}, applied whenever an owner is created. Trims
 * leading/trailing whitespace, collapses runs of whitespace to a single space, upper-cases, and expands
 * common street-type abbreviations as whole words ({@code ST -> STREET}, {@code RD -> ROAD},
 * {@code AVE -> AVENUE}). So {@code '  12  main  st '} becomes {@code '12 MAIN STREET'} and
 * {@code '7 elm ave'} becomes {@code '7 ELM AVENUE'}. A {@code null} or whitespace-only address
 * normalizes to the empty string.
 *
 * <p>This is the single normalized form used everywhere an address matters: it is what
 * {@link NormalizeAddress} stores on the request (so it is persisted and returned) and what
 * {@link RequireOwnerFields} tests for blankness. (The household id is keyed on last name and
 * postcode, not the address — see {@link HouseholdId}.)
 */
public final class AddressNormalizer {

    private static final Map<String, String> ABBREVIATIONS = Map.of(
            "ST", "STREET",
            "RD", "ROAD",
            "AVE", "AVENUE");

    private AddressNormalizer() {
    }

    public static String normalize(String value) {
        if (value == null) {
            return "";
        }
        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder result = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                result.append(' ');
            }
            result.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
        }
        return result.toString();
    }
}

