package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Validates an owner request's optional {@code postcode}. When absent (null or blank) the request is
 * accepted unchanged, keeping the create contract backward-compatible. When present the postcode must be
 * exactly four digits and, for a city whose region is known (via {@link Locality}), must fall within that
 * region's range (see {@link PostcodeRanges}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no
 * known region accepts any 4-digit postcode. A malformed or out-of-range postcode is rejected via
 * {@link InvalidPostcodeException}, which the global handler turns into a 400.
 */
public class ValidatePostcode {

    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
        String postcode = request.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return; // postcode is optional; nothing to validate when absent
        }
        if (!postcode.matches("[0-9]{4}")) {
            throw InvalidPostcodeException.malformed(postcode);
        }
        String region = Locality.of(request.getCity());
        int[] range = PostcodeRanges.forRegion(region);
        if (range == null) {
            return; // no known region for this city -> any 4-digit postcode is accepted
        }
        int value = Integer.parseInt(postcode);
        if (value < range[0] || value > range[1]) {
            throw InvalidPostcodeException.outOfRange(postcode, request.getCity(), region, range);
        }
    }
}

===== IdentityKey.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

/**
 * Derives an owner's {@code identityKey}: the single value all duplicate detection is now expressed
 * through. It is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the
 * telephone is normalized to E.164 the same way as {@link NormalizeTelephone}/{@link TelephoneE164},
 * the email is trimmed and lower-cased (empty when absent or blank, the same form as
 * {@link NormalizeEmail}), and the household component is {@link HouseholdId} over the last name and
 * postcode. Because the telephone is part of the key, two members of the same household (same
 * {@code householdId}) with different telephones derive different identityKeys.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    public static String of(String telephone, String email, String lastName, String postcode) {
        String normalizedTelephone = TelephoneE164.normalizeOrNull(telephone);
        if (normalizedTelephone == null) {
            normalizedTelephone = telephone == null ? "" : telephone.trim();
        }
        String normalizedEmail = (email == null || email.isBlank())
                ? "" : email.trim().toLowerCase(Locale.ROOT);
        String householdId = HouseholdId.of(lastName, postcode);
        return normalizedTelephone + "|" + normalizedEmail + "|" + householdId;
    }
}

